const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let sheet='main',page=1,total=0,meta,request=0,timer,include=[],exclude=[];
const ids=['search','category','status','pool','translation','match','sort'];
const fmt=n=>n.toLocaleString('en');
const label=s=>({candidate:'Screened draft',hold:'Held / unassessed',exclude:'Excluded'}[s]||s);
function params(){const p=new URLSearchParams({sheet,page,size:50});for(const id of ids)if($('#'+id).value)p.set(id,$('#'+id).value);include.forEach(t=>p.append('tag',t));exclude.forEach(t=>p.append('without',t));return p}
function chips(){ $('#chosen-tags').innerHTML=[...include.map(t=>[t,false]),...exclude.map(t=>[t,true])].map(([t,no])=>`<span class="chip ${no?'excluded':''}">${no?'−':'+'} ${esc(t)}<button data-remove="${esc(t)}" aria-label="Remove tag filter">×</button></span>`).join('');$('#chosen-tags').querySelectorAll('button').forEach(b=>b.onclick=()=>{include=include.filter(t=>t!==b.dataset.remove);exclude=exclude.filter(t=>t!==b.dataset.remove);chips();page=1;load()})}
function tagOptions(){const query=$('#tag-search').value.toLowerCase();const tags=meta.tags.filter(t=>t.toLowerCase().includes(query));$('#tag-options').innerHTML=tags.slice(0,35).map(t=>`<div class="tag-option"><span>${esc(t)}</span><button data-tag="${esc(t)}" data-no="0" aria-label="Include ${esc(t)}">+</button><button data-tag="${esc(t)}" data-no="1" aria-label="Exclude ${esc(t)}">−</button></div>`).join('');$('#tag-options').querySelectorAll('button').forEach(b=>b.onclick=()=>{const t=b.dataset.tag;include=include.filter(x=>x!==t);exclude=exclude.filter(x=>x!==t);(b.dataset.no==='1'?exclude:include).push(t);chips();page=1;load()})}
async function load(){const seq=++request;$('#total').textContent='Loading…';$('#error').hidden=true;try{const r=await fetch('/api/questions?'+params());if(!r.ok)throw Error('Could not load questions.');const d=await r.json();if(seq!==request)return;total=d.total;$('#total').textContent=fmt(total)+' questions';$('#range').textContent=total?`${fmt((page-1)*50+1)}–${fmt(Math.min(page*50,total))}`:'';$('#page').textContent=`${page} / ${Math.max(1,Math.ceil(total/50))}`;$('#prev').disabled=page===1;$('#next').disabled=page*50>=total;$('#empty').hidden=!!total;$('#rows').innerHTML=d.rows.map(q=>`<tr><td><button class="question-link" data-id="${esc(q.id)}">${esc(q.text)}</button><div class="inline-answers">${q.choices.map((choice,i)=>`<div class="inline-answer ${i===q.correct?'is-correct':''}"><span class="option-letter">${'ABCD'[i]}</span><span>${esc(choice)}</span>${i===q.correct?'<span class="correct-label">✓ Correct</span>':''}</div>`).join('')}</div><small><a class="question-id-link" data-id="${esc(q.id)}" href="/?question=${encodeURIComponent(q.id)}" title="View English and Ukrainian translation">${esc(q.id)} ↗</a></small></td><td><button class="metadata-button" data-id="${esc(q.id)}" title="Edit category">${esc(q.category)} ✎</button></td><td><button class="badge ${esc(q.status)}" data-id="${esc(q.id)}" title="Edit review status">${label(q.status)} ✎</button></td><td><button class="tag-count metadata-button" data-id="${esc(q.id)}" title="Edit personal tags">${q.tags.length} tags ✎</button>${q.tags.filter(t=>t.startsWith('reason:')||t.startsWith('EU')).slice(0,2).map(t=>`<span class="chip">${esc(t)}</span>`).join('')}</td></tr>`).join('');$('#rows').querySelectorAll('[data-id]').forEach(b=>b.onclick=e=>{e.preventDefault();detail(b.dataset.id)});}catch(e){if(seq!==request)return;$('#total').textContent='Unavailable';$('#error').hidden=false;$('#error').textContent=e.message}}
async function detail(id){try{const r=await fetch('/api/detail?'+new URLSearchParams({id}));if(!r.ok)throw Error('Question unavailable');const d=await r.json(),q=d.source;const block=(title,text,choices)=>`<section><h3>${title}</h3><p>${esc(text)}</p>${choices.map((c,i)=>`<div class="answer ${i===q.correct?'correct':''}">${'ABCD'[i]} · ${esc(c)}${i===q.correct?' ✓':''}</div>`).join('')}</section>`;$('#detail-content').innerHTML=`<p class="source-note">${esc(q.id)} · ${esc(q.category)} · Correct answer: ${'ABCD'[q.correct]}</p><div class="columns">${block('ENGLISH · SOURCE',q.text,q.choices)}${d.ukrainian?block('UKRAINIAN · '+esc(d.ukrainian.status).toUpperCase(),d.ukrainian.text,d.ukrainian.choices):'<section><h3>UKRAINIAN</h3><p>No translation available.</p></section>'}</div>${editorForm(d)}<div class="alltags"><h3>Backend tags</h3>${q.tags.map(t=>`<span class="chip">${esc(t)}</span>`).join('')}</div><p class="source-note">OpenTriviaQA contributors · ${esc(q.source.license)}<br>Source revision: ${esc(q.source.revision)}<br>Titles, facts and draft translations still require verification.</p>`;{const url=new URL(location.href);url.searchParams.set('question',id);history.replaceState(null,'',url);if(!$('#detail').open)$('#detail').showModal();$('#edit-form').onsubmit=e=>saveEdit(e,q.id,d.editRevision)}}catch(e){$('#error').hidden=false;$('#error').textContent=e.message}}
function reset(){ids.forEach(id=>$('#'+id).selectedIndex!==undefined?$('#'+id).selectedIndex=0:$('#'+id).value='');$('#tag-search').value='';include=[];exclude=[];page=1;chips();if(sheet==='ua')$('#pool').value='potential';tagOptions()}
function sheetInfo(){const notes={fun:'Fun Bank · English candidates under the four requested heavy filters. Undated culture references are held for era review. Ukrainian translations stay linked by ID. Status badges refer to the separate EU review.',main:'Main / US · Complete English master. All questions retained, including religion and filtered records.',eu:'EU · Main English bank minus audience and content filters. Ukrainian translation issues do not remove English questions. Includes unassessed survivors; not all questions have had semantic review.',ua:`UA · All ${fmt(meta.counts.ua)} Ukrainian drafts. Defaults to ${fmt(meta.counts.uaPotential)} potential questions; most still await semantic review. Choose “All in this sheet” to inspect excluded and held translations.`};$('#sheet-note').textContent=notes[sheet];document.querySelectorAll('[data-sheet]').forEach(b=>b.classList.toggle('active',b.dataset.sheet===sheet))}
document.querySelectorAll('[data-sheet]').forEach(b=>b.onclick=()=>{sheet=b.dataset.sheet;reset();sheetInfo();load()});
ids.forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',()=>{clearTimeout(timer);page=1;timer=setTimeout(load,id==='search'?220:0)}));
$('#detail').addEventListener('close',()=>{const url=new URL(location.href);url.searchParams.delete('question');history.replaceState(null,'',url)});
$('#tag-search').oninput=tagOptions;$('#reset').onclick=()=>{reset();load()};$('#prev').onclick=()=>{page--;load()};$('#next').onclick=()=>{page++;load()};$('#close').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail'))$('#detail').close()};
for(const format of ['csv','json'])$('#'+format).onclick=()=>{const p=params();p.set('format',format);window.location.href='/api/export?'+p};
try{const r=await fetch('/api/meta');if(!r.ok)throw Error('Dashboard data could not load.');meta=await r.json();for(const s of ['main','eu','ua','fun'])$('#'+s+'-count').textContent=fmt(meta.counts[s]);$('#category').innerHTML+=[...meta.categories].map(c=>`<option>${esc(c)}</option>`).join('');sheetInfo();tagOptions();await load();const question=new URLSearchParams(location.search).get('question');if(question)await detail(question)}catch(e){$('#total').textContent='Unavailable';$('#error').hidden=false;$('#error').textContent=e.message}

function editorForm(d){
 const edit=d.edit||{},statuses=edit.status||{};
 const statusOptions=lang=>[['','Automatic / inherit'],['candidate','Screened draft · include'],['hold','Hold · exclude from pool'],['exclude','Exclude']].map(([v,name])=>`<option value="${v}" ${statuses[lang]===v?'selected':''} ${lang==='uk'&&v==='candidate'&&!d.ukrainian?'disabled':''}>${name}</option>`).join('');
 return `<form id="edit-form" class="editor-form"><h3>Edit editorial metadata</h3><div class="edit-grid"><label>Category<select id="edit-category"><option value="">Original · ${esc(d.originalCategory)}</option>${meta.categories.map(c=>`<option ${edit.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>EU English status<select id="edit-en">${statusOptions('en')}</select></label><label>EU Ukrainian status<select id="edit-uk">${statusOptions('uk')}</select></label></div><label>Personal tags · separate with commas<textarea id="edit-tags" rows="2" placeholder="party-favourite, needs-fact-check">${esc((edit.tags||[]).map(t=>t.replace(/^custom:manual:/,'')).join(', '))}</textarea></label><p class="source-note">Category and status changes apply across sheets. Status controls EU membership; automatic filter tags below retain their evidence. Personal tags are editable. Original questions and answers are preserved.</p><div class="editor-actions"><button id="save-edit" type="submit">Save changes</button><span id="edit-feedback" role="status"></span></div><p class="source-note">${d.editHistory.length} saved change(s) for this question. Set fields to Automatic/Original and clear personal tags to restore inherited values.</p></form>`;
}
async function saveEdit(event,id,revision){
 event.preventDefault();const button=$('#save-edit');button.disabled=true;$('#edit-feedback').textContent='Saving and rebuilding the bank…';
 const status={};for(const lang of ['en','uk'])if($('#edit-'+lang).value)status[lang]=$('#edit-'+lang).value;
 try{
  const r=await fetch('/api/edit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,revision,category:$('#edit-category').value,status,tags:$('#edit-tags').value.split(/[,\n]/).map(t=>t.trim()).filter(Boolean)})});
  if(!r.ok)throw Error('The edit could not be saved.');const result=await r.json();if(result.error)throw Error(result.error);
  meta=await (await fetch('/api/meta')).json();for(const s of ['main','eu','ua','fun'])$('#'+s+'-count').textContent=fmt(meta.counts[s]);
  tagOptions();await load();await detail(id);$('#edit-feedback').textContent='Saved to the bank.';
 }catch(error){$('#edit-feedback').textContent=error.message;button.disabled=false;}
}
